<template><view class="page"><MeetingContentHeader title="会议酒店" :activity-id="activityId"/><view v-if="loading" class="state">加载中...</view><view v-else class="list"><view v-for="hotel in hotels" :key="hotel.hotelId" class="hotel"><image v-if="hotel.coverUrl" :src="hotel.coverUrl" mode="aspectFill"/><view class="title">{{hotel.hotelName}}</view><view class="sub">{{hotel.address}} {{hotel.phone}}</view><view v-for="room in hotel.rooms" :key="room.roomId" class="room"><view><b>{{room.roomName}}</b><text>{{room.bedType}}</text><text>¥{{room.price}}</text></view><button size="mini" :disabled="room.available===0" @click="choose(hotel,room)">{{room.available===0?'售罄':'预订'}}</button></view></view><view v-if="!hotels.length" class="state">暂无可预订酒店</view></view><view v-if="selected.roomId" class="booking"><view>{{selected.hotelName}} · {{selected.roomName}}</view><input v-model="form.checkInDate" placeholder="入住日期 YYYY-MM-DD"/><input v-model="form.checkOutDate" placeholder="离店日期 YYYY-MM-DD"/><button @click="submit">提交预订申请</button></view></view></template>
<script setup>import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import MeetingContentHeader from'@/components/MeetingContentHeader.vue';import{bookHotel,getHotels}from'@/api/portal/hotel';const activityId=ref(''),hotels=ref([]),loading=ref(true),selected=ref({}),form=ref({checkInDate:'',checkOutDate:''});onLoad(o=>{activityId.value=o?.activityId||'';getHotels(activityId.value).then(r=>hotels.value=r.data?.hotels||[]).finally(()=>loading.value=false)});function choose(h,r){selected.value={hotelId:h.hotelId,hotelName:h.hotelName,roomId:r.roomId,roomName:r.roomName}}function submit(){bookHotel({activityId:activityId.value,hotelId:selected.value.hotelId,roomId:selected.value.roomId,roomCount:1,...form.value}).then(()=>{uni.showToast({title:'预订申请已提交'});selected.value={}})}</script><style scoped>.page{min-height:100vh;background:#f5f7fa;padding-bottom:270rpx}.list{padding:110rpx 24rpx 24rpx}.hotel{padding:24rpx;margin-bottom:18rpx;background:#fff;border-radius:16rpx}.hotel image{width:100%;height:230rpx;border-radius:12rpx}.title{margin:14rpx 0;font-weight:600}.sub{color:#909399;font-size:24rpx}.room{display:flex;justify-content:space-between;align-items:center;margin-top:16rpx;padding-top:16rpx;border-top:1px solid #eee}.room text{margin-left:12rpx;color:#909399;font-size:24rpx}.booking{position:fixed;bottom:0;left:0;right:0;padding:24rpx;background:#fff;box-shadow:0 -3rpx 12rpx #ddd}.booking input{margin:12rpx 0;padding:16rpx;background:#f5f7fa}.booking button{background:#1f6feb;color:#fff}.state{padding:180rpx 24rpx;text-align:center;color:#909399}</style>
